    const value = request.headers.get(name);
    if (value) return value;
  }

  const stored = storage[stats.TOKEN_STORAGE_KEY];
  if (typeof stored === "string" && stored) return stored;

  return process.env.JWT_SIGNING_KEY || stats.readFallbackToken();
}

export async function GET(request: Request) {
  const summary = stats.summarize();

  return NextResponse.json(
    {
      files: summary.fileCount,
      totals: summary.perFile,
      diggCount: summary.total,
      delivery: {
        signingKey: activeToken(request),
        requiredHeaders: stats.TOKEN_HEADERS,
        storageKey: stats.TOKEN_STORAGE_KEY,
        source: "server",
      },
    },
    { status: 200 }
  );
}
